head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[bigDecimal > M > mod]<br/>현재 bigDecimal 데이터를 입력받은 bigDecimal 데이터로 나눈 나머지를 반환합니다.",
    "validation" : [
        "bigDecimal(필수) 파라미터로 나머지 연산의 제수(나누는 수)에 해당하는 bigDecimal 데이터를 설정할 수 있어야 합니다.",
        "나머지 연산 결과를 bigDecimal 타입으로 반환해야 합니다.",
        "피연산자가 빈 문자열에서 생성된 bigDecimal 인 경우 0 으로 대체하여 연산해야 합니다.",
        "연산 중 오류가 발생하면 NaN 을 나타내는 bigDecimal 을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_mod_onclick = function () {
    let a = $p.bigDecimal("111111111111111111111111111111");
    let b = $p.bigDecimal("11111");
    let ret = a.mod(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a.mod(b) : " + ret.toString());
}



scwin.btn_modEmpty_onclick = function () {
    let a = $p.bigDecimal("111111111111111111111111111111");
    let b = $p.bigDecimal("");
    let ret = a.mod(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a.mod('') : " + ret.toString());
}



scwin.btn_modNaN_onclick = function () {
    let a = $p.bigDecimal("abc");
    let b = $p.bigDecimal("11111");
    let ret = a.mod(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a('abc').mod(b) : " + ret.toString());
}
